deck_style.css:
/* Rollout deck style on Meridian: a dated timeline, a KPI band and notes. The template's callout and bullets are reused. */
.dk-timeline {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: 1fr;
  gap: var(--space-md);
  margin: 0;
  padding: 0;
  list-style: none;
  border-top: 4px solid var(--brand-core-primary);
}
.dk-timeline li {
  position: relative;
  padding-top: var(--space-md);
  font-size: var(--fs-body);
  color: var(--brand-core-text);
}
/* A dot on the rule above each milestone. */
.dk-timeline li::before {
  content: "";
  position: absolute;
  top: -9px;
  left: 0;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--brand-core-primary);
}
.dk-timeline time {
  display: block;
  margin-bottom: 4px;
  font-size: var(--fs-eyebrow);
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--brand-core-primary);
}

.dk-kpi-band {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: 1fr;
  margin: 0;
  padding: var(--space-md) 0;
  border-top: 1px solid var(--brand-core-border);
  border-bottom: 1px solid var(--brand-core-border);
}
.dk-kpi-band > div { padding: 0 var(--space-md); border-left: 1px solid var(--brand-core-border); }
.dk-kpi-band > div:first-child { padding-left: 0; border-left: 0; }
.dk-kpi-value {
  display: block;
  font-size: var(--fs-title);
  font-weight: 700;
  line-height: 1.1;
  font-variant-numeric: tabular-nums;
  color: var(--brand-core-primary);
}
.dk-kpi-label { display: block; margin-top: 4px; font-size: var(--fs-body); color: var(--brand-core-text); }

.dk-note { margin: var(--space-sm) 0 0; font-size: var(--fs-caption); color: var(--brand-core-muted); }
